// @vitest-environment jsdom
import React from 'react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { act, cleanup, render, renderHook, screen } from '@testing-library/react';
import { clearAuthToken, setAuthToken } from '@/utils/authToken';
import { useVaultUpload, type VaultUploadFileStatus, type VaultUploadOutcome } from '../useVaultUpload';
import { stageFiles, VaultUploadStaging } from '../surfaces/VaultUploadStaging';
import { stubIngestXhr, type IngestInit } from './_ingest-xhr-fake';

const PROGRAM = '11111111-1111-4111-8111-111111111111';
const DOCUMENT = '22222222-2222-4222-8222-222222222222';
const PREVIOUS = '33333333-3333-4333-8333-333333333333';
const file = () => new File(['synthetic bytes'], 'receipt.pdf', { type: 'application/pdf' });
const receipt = () => ({
  success: true,
  document: { id: DOCUMENT, programId: PROGRAM, documentCode: 'receipt.pdf', documentTitle: 'Receipt', version: '1.0', extraction: 'extracted' },
  filing: { folderId: 'module-3', folderLabel: 'Module 3 · Quality', placementStatus: 'confirmed', needsReview: false },
});
const doc = (patch: Record<string, unknown>) => ({ ...receipt(), document: { ...receipt().document, ...patch } });
const filing = (patch: Record<string, unknown>) => ({ ...receipt(), filing: { ...receipt().filing, ...patch } });
const reupload = (patch: Record<string, unknown> = {}) => ({
  ...receipt(), reupload: { unchanged: true, changes: [], differs: [], ...patch },
});

afterEach(() => { cleanup(); vi.unstubAllGlobals(); clearAuthToken(); });

const malformed: Array<[string, unknown, number]> = [
  ['null body', null, 201], ['empty body', {}, 201], ['array body', [receipt()], 201], ['scalar body', 'ok', 201],
  ['missing success', { document: receipt().document, filing: receipt().filing }, 201],
  ['false success', { ...receipt(), success: false }, 201], ['string success', { ...receipt(), success: 'true' }, 201],
  ['contradictory error', { ...receipt(), error: { code: 'FAILED' } }, 201],
  ['missing document', { success: true, filing: receipt().filing }, 201],
  ['null document', { ...receipt(), document: null }, 201], ['array document', { ...receipt(), document: [] }, 201],
  ['missing document id', doc({ id: undefined }), 201], ['blank document id', doc({ id: '' }), 201],
  ['placeholder document id', doc({ id: 'doc-new' }), 201], ['numeric document id', doc({ id: 42 }), 201],
  ['another project', doc({ programId: PREVIOUS }), 201], ['missing project', doc({ programId: undefined }), 201],
  ['another file in this project', doc({ documentCode: 'another-file.pdf' }), 201],
  ['invalid title', doc({ documentTitle: {} }), 201], ['invalid assigned version', doc({ version: {} }), 201],
  ['missing assigned version', doc({ version: undefined }), 201], ['blank assigned version', doc({ version: ' \t' }), 201],
  ['missing stored title', doc({ documentTitle: undefined }), 201],
  ['invalid extraction state', doc({ extraction: 'complete' }), 201],
  ['missing filing', { success: true, document: receipt().document }, 201],
  ['invalid folder label', filing({ folderLabel: {} }), 201], ['invalid folder id', filing({ folderId: 12 }), 201],
  ['blank folder id', filing({ folderId: '  ' }), 201], ['missing placement', filing({ placementStatus: undefined }), 201],
  ['unfiled without needed review', filing({ folderId: null, placementStatus: 'unfiled', needsReview: false }), 201],
  ['unknown placement', filing({ placementStatus: 'archived' }), 201],
  ['string review flag', filing({ needsReview: 'false' }), 201], ['contradictory review flag', filing({ needsReview: true }), 201],
  ['confirmed placement without folder', filing({ folderId: null }), 201],
  ['missing reupload on HTTP200', receipt(), 200], ['reupload on HTTP201', reupload(), 201],
  ['accepted without the route status', receipt(), 202], ['no-content status', receipt(), 204],
  ['invalid reupload differences', reupload({ differs: {} }), 200],
  ['invalid difference row', reupload({ differs: [null] }), 200],
  ['unknown difference field', reupload({ differs: [{ field: 'not_a_field', recorded: null, requested: 'x' }] }), 200],
  ['invalid recorded difference', reupload({ differs: [{ field: 'document_title', recorded: 1, requested: 'x' }] }), 200],
  ['string unchanged flag', reupload({ unchanged: 'true' }), 200],
  ['false unchanged with no changes', reupload({ unchanged: false }), 200],
  ['true unchanged despite changes', reupload({ changes: [{ field: 'storage_version_id', from: null, to: 'stored' }] }), 200],
  ['invalid change row', reupload({ unchanged: false, changes: [null] }), 200],
  ['nontext change before value', reupload({ unchanged: false, changes: [{ field: 'storage_version_id', from: 0, to: 'stored' }] }), 200],
  ['missing requested difference value', reupload({ differs: [{ field: 'folder_id', recorded: null }] }), 200],
  ['equal change values', reupload({ unchanged: false, changes: [{ field: 'storage_version_id', from: null, to: null }] }), 200],
  ['equal requested and recorded values', reupload({ differs: [{ field: 'document_title', recorded: 'Receipt', requested: 'Receipt' }] }), 200],
  ['duplicate change fields', reupload({ unchanged: false, changes: [
    { field: 'storage_version_id', from: null, to: 'a' }, { field: 'storage_version_id', from: 'a', to: 'b' },
  ] }), 200],
  ['duplicate difference fields', reupload({ differs: [
    { field: 'document_title', recorded: 'Old', requested: 'New' }, { field: 'document_title', recorded: 'Old', requested: 'Other' },
  ] }), 200],
];

describe('Vault upload receipts: a successful HTTP status does not confirm a write', () => {
  it.each(malformed)('keeps %s unconfirmed', async (_name, body, status) => {
    const answer = stubIngestXhr(vi.fn(async () => ({ status, json: async () => body })));
    const { result, rerender } = renderHook(() => useVaultUpload(PROGRAM));
    const statuses: VaultUploadFileStatus[] = [];
    let outcome!: Awaited<ReturnType<typeof result.current.upload>>;
    await act(async () => { outcome = await result.current.upload([file()], { onFileStatus: (_i, value) => statuses.push(value) }); });
    expect(outcome.succeeded).toEqual([]);
    expect(outcome.recorded).toEqual([]);
    expect(outcome.filings).toEqual([]);
    expect(outcome.newVersions).toEqual([]);
    expect(outcome.alreadyRecorded).toEqual([]);
    expect(outcome.conflicts).toEqual([]);
    expect(outcome.failed).toEqual([expect.objectContaining({ name: 'receipt.pdf', unknown: true })]);
    expect(statuses.at(-1)).toMatchObject({ state: 'refused', unknown: true });
    expect(statuses.some((status) => status.state === 'stored')).toBe(false);
    expect(result.current.uploading).toBe(false);
    expect(result.current.note?.tone).toBe('error');
    expect(result.current.note?.text).toMatch(/Reload the Vault and check before trying again/);
    expect(result.current.note?.text).toMatch(/not known whether.*recorded/i);
    expect(result.current.note?.text).not.toMatch(/Not filed|Nothing partial was recorded/);
    rerender();
    await act(async () => { await Promise.resolve(); });
    expect(answer).toHaveBeenCalledTimes(1);
  });

  it('keeps an unreadable successful reply unconfirmed and sends no retry', async () => {
    const answer = stubIngestXhr(vi.fn(async () => ({ status: 201, json: async () => { throw new SyntaxError('synthetic invalid JSON'); } })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    await act(async () => {
      const outcome = await result.current.upload([file()]);
      expect(outcome.succeeded).toEqual([]);
      expect(outcome.failed[0]).toMatchObject({ unknown: true });
    });
    expect(answer).toHaveBeenCalledTimes(1);
  });

  it('does not confirm the previous version as its own replacement', async () => {
    stubIngestXhr(vi.fn(async () => ({ status: 201, json: async () => doc({ id: PREVIOUS, documentCode: 'original.pdf', version: '2.0' }) })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    await act(async () => {
      const outcome = await result.current.upload([file()], { newVersionOf: { documentId: PREVIOUS, title: 'Original' } });
      expect(outcome.succeeded).toEqual([]);
      expect(outcome.recorded).toEqual([]);
      expect(outcome.newVersions).toEqual([]);
      expect(outcome.failed[0]).toMatchObject({ unknown: true });
    });
  });

  it('preserves the server’s explicit uncertain-commit result without claiming nothing was recorded', async () => {
    const answer = stubIngestXhr(vi.fn(async () => ({ status: 503, json: async () => ({
      error: { code: 'OUTCOME_UNKNOWN', message: 'The Vault admission outcome could not be confirmed. Review the current Vault records before trying again.' },
    }) })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    let last!: VaultUploadFileStatus;
    await act(async () => {
      const outcome = await result.current.upload([file()], { onFileStatus: (_i, value) => { last = value; } });
      expect(outcome.recorded).toEqual([]);
      expect(outcome.failed[0]).toMatchObject({ unknown: true });
    });
    expect(last).toMatchObject({ state: 'refused', unknown: true });
    expect(result.current.note?.text).not.toMatch(/Not filed|Nothing partial was recorded/);
    expect(answer).toHaveBeenCalledTimes(1);
  });
});

describe('Vault upload receipts: valid committed responses keep their actual meaning', () => {
  it('records the returned identity and exact filing, permitting extra response fields', async () => {
    stubIngestXhr(vi.fn(async () => ({ status: 201, json: async () => ({ ...receipt(), futureMetadata: { available: true } }) })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    await act(async () => {
      const outcome = await result.current.upload([file()]);
      expect(outcome.succeeded).toEqual(['receipt.pdf']);
      expect(outcome.recorded).toEqual([DOCUMENT]);
      expect(outcome.filings[0]).toMatchObject({ placement: 'confirmed', folderLabel: 'Module 3 · Quality' });
      expect(outcome.failed).toEqual([]);
    });
  });

  it('honors explicit Unfiled despite a retained old folder and accepts a legacy null title', async () => {
    const body = { ...reupload({ differs: [{ field: 'document_title', recorded: null, requested: 'receipt' }] }), document: { ...receipt().document, documentTitle: null }, filing: { ...receipt().filing, placementStatus: 'unfiled', needsReview: true } };
    stubIngestXhr(vi.fn(async () => ({ status: 200, json: async () => body })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    const statuses: VaultUploadFileStatus[] = [];
    await act(async () => {
      const outcome = await result.current.upload([file()], { onFileStatus: (_i, value) => statuses.push(value) });
      expect(outcome.recorded).toEqual([DOCUMENT]);
      expect(outcome.alreadyRecorded[0]).toMatchObject({ name: 'receipt.pdf' });
      expect(statuses.at(-1)).toMatchObject({ state: 'stored', placement: 'unfiled', folderLabel: null });
    });
    expect(result.current.note?.text).not.toMatch(/Auto-filed|Module 3/);
    expect(result.current.note?.text).not.toContain('(as "receipt.pdf")');
  });

  it('reports a valid repaired reupload without claiming nothing changed in the row or batch', async () => {
    const body = reupload({ unchanged: false, changes: [{ field: 'storage_version_id', from: null, to: 'stored-copy' }] });
    stubIngestXhr(vi.fn(async () => ({ status: 200, json: async () => body })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    let last!: VaultUploadFileStatus;
    await act(async () => {
      const outcome = await result.current.upload([file()], { onFileStatus: (_i, value) => { last = value; } });
      expect(outcome.recorded).toEqual([DOCUMENT]);
      expect(outcome.alreadyRecorded[0]).toMatchObject({ updated: true });
    });
    expect(last).toMatchObject({ state: 'stored', recordUpdated: true });
    expect(result.current.note?.text).toMatch(/record was updated/i);
    expect(result.current.note?.text).not.toMatch(/nothing changed/i);
    const staging = stageFiles({ files: [{ file: file(), path: 'receipt.pdf' }], unread: 0 }, 'OTHER');
    staging.rows[0].status = last;
    render(<VaultUploadStaging staging={staging} folders={[]} uploading={false} onChange={vi.fn()} onRemove={vi.fn()} onUpload={vi.fn()} onDone={vi.fn()} />);
    expect(screen.getByTestId('vault-stage-row').textContent).toMatch(/record was updated/i);
    expect(screen.getByTestId('vault-stage-row').textContent).not.toMatch(/nothing was changed/i);
  });

  it('keeps a valid new version with its retained code and server-assigned version', async () => {
    const answer = stubIngestXhr(vi.fn(async (_url: string, _init: IngestInit) => ({ status: 201, json: async () => doc({ documentCode: 'original.pdf', version: 'revision-7B', extraction: 'pending' }) })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    let last!: VaultUploadFileStatus;
    await act(async () => {
      const outcome = await result.current.upload([file()], { newVersionOf: { documentId: PREVIOUS, title: 'Earlier request title' }, onFileStatus: (_i, value) => { last = value; } });
      expect(outcome.recorded).toEqual([DOCUMENT]);
      expect(outcome.newVersions).toEqual([{ name: 'receipt.pdf', version: 'revision-7B', title: 'Receipt', folderLabel: 'Module 3 · Quality' }]);
      expect(outcome.failed).toEqual([]);
      expect(outcome.filings).toEqual([]);
      expect(outcome.alreadyRecorded).toEqual([]);
    });
    expect(last).toMatchObject({ state: 'stored', readingText: true });
    const form = answer.mock.calls[0][1].body as FormData;
    expect(form.get('supersedesDocumentId')).toBe(PREVIOUS);
    expect(form.get('documentCode')).toBeNull();
    expect(form.get('version')).toBeNull();
    expect(form.get('documentTitle')).toBe('Earlier request title');
    expect(result.current.note?.text).toContain('to "Receipt" as vrevision-7B');
    expect(result.current.note?.text).not.toContain('Earlier request title');
    expect(result.current.uploading).toBe(false);
    expect(answer).toHaveBeenCalledTimes(1);
  });

  it('continues a mixed batch after a malformed receipt without counting it or retrying it', async () => {
    const answer = stubIngestXhr(vi.fn(async (_url, init) => {
      const code = String((init.body as FormData).get('documentCode'));
      return { status: 201, json: async () => code === 'bad.pdf' ? null : doc({
        id: code === 'first.pdf' ? DOCUMENT : PREVIOUS, documentCode: code,
      }) };
    }));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    await act(async () => {
      const outcome = await result.current.upload(['first.pdf', 'bad.pdf', 'last.pdf'].map((name) => new File(['synthetic bytes'], name)));
      expect(outcome.succeeded).toEqual(['first.pdf', 'last.pdf']);
      expect(outcome.recorded).toEqual([DOCUMENT, PREVIOUS]);
      expect(outcome.failed).toEqual([expect.objectContaining({ name: 'bad.pdf', unknown: true })]);
    });
    expect(answer).toHaveBeenCalledTimes(3);
    expect(result.current.note?.text).toMatch(/Filed 2.*not known whether/s);
  });
});


/** Exact unknown outcome, shared by raw-JSON and check-in recovery controls. */
function expectUnconfirmed(outcome: VaultUploadOutcome) {
  expect(outcome).toEqual({
    succeeded: [], recorded: [], filings: [], alreadyRecorded: [], conflicts: [], newVersions: [],
    failed: [{ name: 'receipt.pdf', reason: expect.any(String), unknown: true }],
  });
  expect(outcome.failed[0].reason).not.toMatch(/nothing.*recorded|no reply arrived/i);
}

describe('Vault upload receipts: consolidated transport and caller safeguards', () => {
  // The shared fake serializes a rejected json() as null. Exercise actual
  // responseText parsing failure over the existing sendIngest XHR seam too.
  it.each(['', '<html>upstream response</html>', '{"success":'])('settles an undecodable successful raw response %j without retry', async (text) => {
    const sent = vi.fn();
    class RawReplyXhr {
      status = 201;
      responseText = text;
      withCredentials = false;
      upload = {};
      onload: (() => void) | null = null;
      open() { /* Real sendIngest owns the request. */ }
      setRequestHeader() { /* Authentication is checked by the positive controls. */ }
      send(body: unknown) { sent(body); globalThis.queueMicrotask(() => this.onload?.()); }
    }
    vi.stubGlobal('XMLHttpRequest', RawReplyXhr);
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    const statuses: VaultUploadFileStatus[] = [];
    let outcome!: VaultUploadOutcome;
    await act(async () => { outcome = await result.current.upload([file()], { onFileStatus: (_i, value) => statuses.push(value) }); });
    expectUnconfirmed(outcome);
    expect(statuses.at(-1)).toMatchObject({ state: 'refused', unknown: true });
    expect(statuses.some((status) => status.state === 'stored')).toBe(false);
    expect(result.current.uploading).toBe(false);
    expect(result.current.note?.text).toMatch(/Reload the Vault and check/);
    expect(sent).toHaveBeenCalledTimes(1);
  });

  it('continues after both missing and malformed reupload receipts without another POST for either', async () => {
    const bodies = [null, { ...reupload({ differs: [null] }), document: { ...receipt().document, documentCode: 'malformed.pdf' } }, doc({ documentCode: 'confirmed.pdf' })];
    const sent: string[] = [];
    const answer = stubIngestXhr(vi.fn(async (_url: string, init: IngestInit) => {
      sent.push(String((init.body as FormData).get('documentCode')));
      const index = sent.length - 1;
      return { status: index === 1 ? 200 : 201, json: async () => bodies[index] };
    }));
    const statuses: Array<{ index: number; status: VaultUploadFileStatus }> = [];
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    let outcome!: VaultUploadOutcome;
    await act(async () => { outcome = await result.current.upload(['unknown.pdf', 'malformed.pdf', 'confirmed.pdf'].map((name) => new File(['synthetic bytes'], name)), {
      onFileStatus: (index, status) => statuses.push({ index, status }),
    }); });
    expect(sent).toEqual(['unknown.pdf', 'malformed.pdf', 'confirmed.pdf']);
    expect(outcome.succeeded).toEqual(['confirmed.pdf']);
    expect(outcome.recorded).toEqual([DOCUMENT]);
    expect(outcome.failed).toEqual([
      { name: 'unknown.pdf', reason: expect.any(String), unknown: true },
      { name: 'malformed.pdf', reason: expect.any(String), unknown: true },
    ]);
    expect(outcome.filings.map((entry) => entry.name)).toEqual(['confirmed.pdf']);
    expect(outcome.alreadyRecorded).toEqual([]);
    expect(outcome.newVersions).toEqual([]);
    expect(outcome.conflicts).toEqual([]);
    expect(statuses.filter((entry) => entry.status.state === 'stored').map((entry) => entry.index)).toEqual([2]);
    expect(result.current.uploading).toBe(false);
    expect(result.current.note?.text).toMatch(/Filed 1/);
    expect(result.current.note?.text).toMatch(/unknown.pdf; malformed.pdf/);
    expect(answer).toHaveBeenCalledTimes(3);
  });

  const compatible = [
    { label: 'absent extraction and extra future fields', extraction: undefined, folder: 'quality/custom-folder', folderLabel: 'Quality', placement: 'confirmed', reading: false },
    { label: 'extracted with null label and opaque folder code', extraction: 'extracted', folder: 'quality/custom-folder', folderLabel: null, placement: 'suggested', reading: false },
    { label: 'pending with empty label', extraction: 'pending', folder: 'quality/custom-folder', folderLabel: '', placement: 'confirmed', reading: true },
    { label: 'failed extraction stored unfiled', extraction: 'failed', folder: null, folderLabel: '', placement: 'unfiled', reading: false },
  ];
  it.each(compatible)('accepts a real-shaped authenticated receipt: $label', async (item) => {
    setAuthToken('vault-receipt-session');
    const body = { ...receipt(), futureField: { accepted: true },
      document: { ...receipt().document, extraction: item.extraction, futureMetadata: 7 },
      filing: { ...receipt().filing, folderId: item.folder, folderLabel: item.folderLabel,
        placementStatus: item.placement, needsReview: item.folder === null, futureFiling: 'retained' } };
    const answer = stubIngestXhr(vi.fn(async (_url: string, _init: IngestInit) => ({ status: 201, json: async () => body })));
    const statuses: VaultUploadFileStatus[] = [];
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    let outcome!: VaultUploadOutcome;
    await act(async () => { outcome = await result.current.upload([file()], { onFileStatus: (_i, value) => statuses.push(value) }); });
    expect(outcome.succeeded).toEqual(['receipt.pdf']);
    expect(outcome.recorded).toEqual([DOCUMENT]);
    expect(outcome.failed).toEqual([]);
    expect(outcome.filings).toEqual([{ name: 'receipt.pdf', folderLabel: item.folder ? item.folderLabel || item.folder : null,
      needsReview: item.folder === null, placement: item.placement }]);
    expect(statuses.at(-1)).toEqual({ state: 'stored', version: '1.0', folderLabel: item.folder ? item.folderLabel || item.folder : null,
      placement: item.placement, already: false, ...(item.reading ? { readingText: true } : {}) });
    expect(result.current.uploading).toBe(false);
    expect(result.current.note?.tone).toBe('ok');
    const [url, init] = answer.mock.calls[0];
    expect(url).toBe('/api/vault/ingest');
    expect(init.method).toBe('POST');
    expect(init.credentials).toBe('include');
    expect(init.headers.Authorization).toBe('Bearer vault-receipt-session');
    expect(Object.keys(init.headers).map((key) => key.toLowerCase())).not.toContain('content-type');
    expect((init.body as FormData).get('programId')).toBe(PROGRAM);
    expect(answer).toHaveBeenCalledTimes(1);
  });

  it.each([true, false])('keeps detail/filing guidance and repair flags truthful with unchanged=%s', async (unchanged) => {
    const body = reupload({ unchanged,
      changes: unchanged ? [] : [{ field: 'storage_version_id', from: null, to: 'stored-object-version' }],
      differs: [{ field: 'document_title', recorded: 'Receipt', requested: 'Renamed' },
        { field: 'folder_id', recorded: 'module-3', requested: 'module-5' }],
      futureReceiptField: 'accepted',
    });
    const answer = stubIngestXhr(vi.fn(async () => ({ status: 200, json: async () => body })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    let outcome!: VaultUploadOutcome;
    let last!: VaultUploadFileStatus;
    await act(async () => { outcome = await result.current.upload([file()], { onFileStatus: (_i, value) => { last = value; } }); });
    expect(outcome.recorded).toEqual([DOCUMENT]);
    expect(outcome.succeeded).toEqual(['receipt.pdf']);
    expect(outcome.failed).toEqual([]);
    expect(outcome.filings).toEqual([]);
    expect(outcome.newVersions).toEqual([]);
    expect(outcome.alreadyRecorded).toEqual([{ name: 'receipt.pdf', title: 'Receipt', differs: true, filingDiffers: true,
      ...(!unchanged ? { updated: true } : {}) }]);
    expect(last).toMatchObject({ state: 'stored', already: true });
    if (unchanged) {
      expect(last).not.toHaveProperty('recordUpdated');
      expect(result.current.note?.text).toMatch(/nothing changed/i);
      expect(result.current.note?.text).not.toMatch(/record was updated/i);
    } else {
      expect(last).toMatchObject({ recordUpdated: true });
      expect(result.current.note?.text).toMatch(/record was updated/i);
      expect(result.current.note?.text).not.toMatch(/nothing changed/i);
    }
    expect(result.current.note?.text).toMatch(/Already in the Vault/);
    expect(result.current.note?.text).toMatch(/Edit details/);
    expect(result.current.note?.text).toMatch(/Move in its filing/);
    expect(result.current.uploading).toBe(false);
    expect(answer).toHaveBeenCalledTimes(1);
  });

  it.each([null, '', '  '])('uses generic check-in copy for a legacy stored title %j without inventing a title', async (title) => {
    const answer = stubIngestXhr(vi.fn(async () => ({ status: 201, json: async () => doc({ documentCode: 'original.pdf', version: '2.0', documentTitle: title }) })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    await act(async () => {
      const outcome = await result.current.upload([file()], { newVersionOf: { documentId: PREVIOUS, title: 'Earlier request title' } });
      expect(outcome.newVersions).toEqual([{ name: 'receipt.pdf', version: '2.0', title, folderLabel: 'Module 3 · Quality' }]);
      expect(outcome.recorded).toEqual([DOCUMENT]);
      expect(outcome.failed).toEqual([]);
    });
    expect(result.current.note?.text).toContain('Added receipt.pdf to the recorded document as v2.0');
    expect(result.current.note?.text).not.toMatch(/Earlier request title|"null"|"undefined"|"\s*"/);
    expect(result.current.uploading).toBe(false);
    expect(answer).toHaveBeenCalledTimes(1);
  });

  it('keeps a missing-identity check-in unknown without completing its new-version outcome', async () => {
    const answer = stubIngestXhr(vi.fn(async () => ({ status: 201, json: async () => doc({ id: undefined, version: '2.0' }) })));
    const { result } = renderHook(() => useVaultUpload(PROGRAM));
    const statuses: VaultUploadFileStatus[] = [];
    let outcome!: VaultUploadOutcome;
    await act(async () => { outcome = await result.current.upload([file()], {
      newVersionOf: { documentId: PREVIOUS, title: 'Receipt' }, onFileStatus: (_i, value) => statuses.push(value),
    }); });
    expectUnconfirmed(outcome);
    expect(statuses.at(-1)).toMatchObject({ state: 'refused', unknown: true });
    expect(statuses.some((status) => status.state === 'stored')).toBe(false);
    expect(result.current.uploading).toBe(false);
    expect(answer).toHaveBeenCalledTimes(1);
  });
});

/**
 * The one document-upload path — `POST /api/vault/ingest`.
 *
 * ── Why this is a hook and not two copies ────────────────────────────────────
 * There is exactly one endpoint in the product that persists uploaded bytes,
 * computes a SHA-256 of them and writes a governed document row, and until now
 * exactly one surface called it: `v2/surfaces/Vault.tsx`. The MDX lane's own
 * Document vault — the one whose header reads "21 CFR Part 11 audit trail ·
 * SHA-256 chained · 7-year minimum retention" — had an Upload button that
 * opened an AnA chat prompt, so a device team could not put a file into their
 * vault at all.
 *
 * Fixing that by copying forty lines into the MDX surface would have produced
 * the second copy of a governed write path, and the two would have drifted the
 * first time either lane changed a field name or a failure message. The logic
 * moves here and BOTH surfaces call it, which is the same reason
 * `./programAction.ts` exists one level up.
 *
 * ── What the caller gets, and what it must not do ────────────────────────────
 * `upload(files)` resolves to a per-file outcome. It never throws for a
 * rejected file: a partial batch is the normal case (one file over the size
 * limit, one refused by the virus scan) and the caller has to be able to tell
 * the user which ones landed. What it must NOT do is report success it did not
 * observe — `succeeded` counts only validated document receipts, so a surface
 * that refreshes on `succeeded > 0` refreshes on confirmed rows.
 *
 * The server owns every decision that matters: the SHA-256, the storage key,
 * the audit entry, the tenant check. This function's whole job is to hand it
 * the bytes and report back honestly.
 */

import * as React from 'react';
import { redactInternals } from '@/lib/queryClient';
import { getAuthHeaders } from '@/utils/authToken';
import type { VaultClassification, VaultIngestDocumentType } from '@shared/constants/domain/vault-taxonomy';
import { vaultDocumentCodeForFile } from '@shared/constants/domain/vault-document-code';
import { IngestUnconfirmedError, sendIngest, type IngestProgress, type IngestReply } from './vaultIngestTransport';
import { readVaultIngestReceipt } from './vaultIngestReceipt';
export { VAULT_UPLOAD_ACCEPT } from '@shared/constants/document-intake-formats';

export interface VaultUploadOutcome {
  /** Files the server accepted and recorded. */
  succeeded: string[];
  /** The documents those files were recorded as, by the id the server returned
   *  (`document.id`), in the order sent. A response that names none adds none,
   *  so a surface that opens the document just uploaded opens one the server
   *  named, never one it guessed. */
  recorded: string[];
  /** Files without a confirmed receipt: a refusal, or an unknown result after a complete send. */
  failed: Array<{ name: string; reason: string; unknown?: true }>;
  /** Per-file filing outcome, as the server stored it: the classifier's
   *  suggested dossier folder, or unfiled (visible review queue). */
  filings: Array<{ name: string; folderLabel: string | null; needsReview: boolean; placement: VaultPlacement }>;
  /** Files whose exact bytes the Vault already recorded at that code and
   *  version: `updated` identifies a repaired record, and `differs` says the upload asked for a
   *  title, type or classification other than the recorded one (VR-05);
   *  `filingDiffers`, present only when true, a folder, kind or CTD section
   *  (Part 11 review F3). */
  alreadyRecorded: Array<{ name: string; title: string | null; differs: boolean; filingDiffers?: true; updated?: true }>;
  /** Files refused because a different file is already recorded at that name
   *  (409 VERSION_CONTENT_CONFLICT). The surface can offer to add each as the
   *  next version of the recorded document (VR-09), so the File is kept. */
  conflicts: Array<{ name: string; file: File }>;
  /** Versions added to an existing document, with the version the server assigned. */
  newVersions: Array<{ name: string; version: string; title: string | null; folderLabel: string | null }>;
}

/**
 * What the person said about one file, row by row, before it was sent (gap 7.1,
 * docs/design/VEEVA_GAP_2026-10-22.md). Every field is one POST /api/vault/ingest
 * already validates: a blank one is not sent, and the server's default applies
 * (the title from the file name, classification INTERNAL, and a placement the
 * classifier suggests). A folder named here is recorded as a person's filing
 * ('confirmed'), and only with a folder are the evidence kind and CTD section
 * written, so they are sent only with one.
 *
 * No version is sent. A new document is 1.0, and every later version is
 * numbered by the Vault when it is added to its document (VR-08): a typed
 * version under an existing name would be recorded beside that document,
 * unlinked, and a non-numeric one would stop the Vault numbering it later
 * (Part 11 review, 2026-10-22).
 */
export interface VaultUploadFileFields {
  title?: string;
  documentType?: VaultIngestDocumentType;
  classification?: VaultClassification;
  folderId?: string;
  evidenceKind?: string;
  ctdSection?: string;
}

/** How the Vault recorded a file's folder: the person's filing, the classifier's proposal, or none. */
export type VaultPlacement = 'confirmed' | 'suggested' | 'unfiled';

/** Where one file of a batch stands, reported as each settles. */
export type VaultUploadFileStatus =
  /** `sent` of `total` bytes of its request have gone out; once they all have, the server is scanning and storing it. */
  | { state: 'uploading'; sent?: number; total?: number }
  | { state: 'stored'; version: string | null; folderLabel: string | null; placement: VaultPlacement; already: boolean;
      /** Its text is still being read by the server (a scanned PDF's OCR is off the upload, MR-08 Stage 3). */
      readingText?: true; recordUpdated?: true }
  | { state: 'refused'; reason: string; unknown?: true };

export interface VaultUploadOptions {
  /**
   * What the user says the file IS — one of the ingest schema's types
   * (VAULT_INGEST_DOCUMENT_TYPES). When the caller offers no choice, the type
   * is recorded as OTHER rather than guessed from the extension: a file named
   * like a CSR is not grounds to FILE it as a CSR, and document type drives
   * downstream regulatory handling.
   */
  documentType?: VaultIngestDocumentType;
  /**
   * Add the file as the next version of this document (VR-08/09), naming it by
   * one of its versions. The server assigns the version and keeps the
   * document's code and filing, so no document code is sent, and the title is
   * the document's own.
   */
  newVersionOf?: { documentId: string; title: string };
  /** Per-file fields, in the order of `files`. Not used for a new version, which keeps its document's. */
  fields?: ReadonlyArray<VaultUploadFileFields | undefined>;
  /** Told as each file starts and settles, by its index in `files`. */
  onFileStatus?: (index: number, status: VaultUploadFileStatus) => void;
}

export interface VaultUploadState {
  uploading: boolean;
  /** The last outcome, as copy a surface can render directly. */
  note: { tone: 'ok' | 'error'; text: string } | null;
  clearNote: () => void;
  upload: (files: FileList | File[] | null, opts?: VaultUploadOptions) => Promise<VaultUploadOutcome>;
}

/** The default document type. See the note in `uploadOne`. */
const DEFAULT_DOCUMENT_TYPE: VaultIngestDocumentType = 'OTHER';

/** The ingest's filing fields; any other field a re-upload reports is a detail. */
const FILING_FIELDS = new Set(['folder_id', 'evidence_kind', 'ctd_section']);

/** A re-upload the Vault already held: which of its asks were not applied, details or filing. */
function alreadyRecordedOf(differs: Array<{ field?: unknown }>, title: string | null, unchanged: boolean): Omit<VaultUploadOutcome['alreadyRecorded'][number], 'name'> {
  const filing = differs.some((d) => FILING_FIELDS.has(String(d.field)));
  return { title, differs: differs.some((d) => !FILING_FIELDS.has(String(d.field))), ...(filing ? { filingDiffers: true as const } : {}),
    ...(!unchanged ? { updated: true as const } : {}) };
}

/** What the user is told about held files: whether the record changed, and how to change its filing/details. */
function alreadyRecordedText(list: VaultUploadOutcome['alreadyRecorded']): string {
  if (list.length === 0) return '';
  const named = (entries: typeof list) => entries.map((a) => a.title ? `${a.name} (as "${a.title}")` : a.name).join('; ');
  const unchanged = list.filter((a) => !a.updated);
  const updated = list.filter((a) => a.updated);
  const held = unchanged.length ? `Already in the Vault, nothing changed: ${named(unchanged)}.` : '';
  const repaired = updated.length ? ` Already in the Vault: ${named(updated)}. Its record was updated; review its history for details.` : '';
  const details = list.some((a) => a.differs)
    ? ' Its title, type or classification is changed with Edit details, not by uploading it again.'
    : '';
  const filing = list.some((a) => a.filingDiffers)
    ? ' Its folder, kind or CTD section is changed with Move in its filing, not by uploading it again.'
    : '';
  return `${held}${repaired}${details}${filing}`.trim();
}

/** The person's fields, as form entries: only what was given, and the filing details only with a folder. */
function appendFileFields(form: FormData, fields: VaultUploadFileFields | undefined): void {
  const given = (v: string | undefined) => (v && v.trim() ? v.trim() : null);
  if (fields?.classification) form.append('classification', fields.classification);
  const folderId = given(fields?.folderId);
  if (!folderId) return;
  form.append('folderId', folderId);
  const kind = given(fields?.evidenceKind);
  if (kind) form.append('evidenceKind', kind);
  const section = given(fields?.ctdSection);
  if (section) form.append('ctdSection', section);
}

async function uploadOne(
  programId: string,
  file: File,
  documentType: VaultIngestDocumentType,
  how: { newVersionOf?: VaultUploadOptions['newVersionOf']; fields?: VaultUploadFileFields; onProgress?: IngestProgress },
): Promise<
  | {
      ok: true;
      folderLabel: string | null;
      needsReview: boolean;
      placement: VaultPlacement;
      already: Omit<VaultUploadOutcome['alreadyRecorded'][number], 'name'> | null;
      version: string | null;
      documentId: string;
      documentTitle: string | null;
      readingText: boolean;
    }
  | { ok: false; reason: string; code: string | null; unknown?: true }
> {
  const { newVersionOf, fields, onProgress } = how;
  const form = new FormData();
  form.append('file', file);
  form.append('programId', programId);
  if (newVersionOf) {
    /* A check-in: the server finds the document by this version, assigns the
       next version and keeps its code, so neither is sent (a version is
       refused, VERSION_IS_ASSIGNED). */
    form.append('supersedesDocumentId', newVersionOf.documentId);
    form.append('documentTitle', newVersionOf.title);
  } else {
    /* The ingest schema requires a code, a title and a type. The filename is the
       only thing the user has actually told us, so it supplies the first two
       verbatim; the type is the caller's stated choice, defaulting to OTHER. */
    // The file name as uploaded: the same code the data room files this file under (QA-2026-10-08).
    form.append('documentCode', vaultDocumentCodeForFile(file.name, 'document'));
    form.append('documentTitle', fields?.title?.trim() || file.name.replace(/\.[^.]+$/, ''));
    appendFileFields(form, fields);
  }
  form.append('documentType', fields?.documentType ?? documentType);

  let res: IngestReply;
  try {
    /* THE UPLOAD COULD NOT AUTHENTICATE WITHOUT THIS.
       `/api/vault/ingest` is mounted behind `authMiddleware`
       (server/bootstrap/register-inline-routes.ts), whose header reads
       "Validates Bearer JWT tokens only" and which answers a request with no
       Authorization header `401 { error: 'Bearer token required' }`. It reads
       `req.headers.authorization` and has no cookie fallback, so
       `credentials: 'include'` alone never authenticated this request — every
       upload through this hook was refused, on all three of its callers (the
       v2 Vault, the MDX Document vault, the MDX pathway attach).

       The irony worth recording: Etmf.tsx's hand-rolled copy of this request
       — the one the assessment recommended deleting in favour of this hook —
       sent these headers and was the only upload path that worked.

       NO Content-Type here, deliberately: the browser must set it so the
       multipart boundary is generated, and naming it produces a body the
       server cannot parse. `getAuthHeaders()` sets only Authorization and
       x-organization-id. */
    res = await sendIngest(form, { ...getAuthHeaders() }, onProgress);
  } catch (error) {
    // Sending every byte is not a receipt. The server may have committed before the reply was lost.
    if (error instanceof IngestUnconfirmedError) return { ok: false, reason: error.message, code: null, unknown: true };
    return { ok: false, reason: 'the connection dropped before the file was sent', code: null };
  }

  if (res.ok) {
    const body = readVaultIngestReceipt(await res.json().catch(() => null), res.status, {
      programId, fileName: file.name, supersedesDocumentId: newVersionOf?.documentId,
    });
    if (!body) return { ok: false, reason: 'the server reply did not confirm this file in this project', code: null, unknown: true };
    const { document, filing, reupload } = body;
    // Unfiled may retain an old folder in persisted legacy records. Honor the
    // explicit placement just as the tree does, never infer filing from it.
    const folder = filing.placementStatus === 'unfiled' ? null : filing.folderId;
    return {
      ok: true,
      folderLabel: folder ? filing.folderLabel || folder : null,
      needsReview: filing.needsReview,
      placement: filing.placementStatus,
      already: reupload ? alreadyRecordedOf(reupload.differs, document.documentTitle, reupload.unchanged) : null,
      version: document.version,
      documentId: document.id,
      documentTitle: document.documentTitle,
      readingText: document.extraction === 'pending',
    };
  }

  const body = (await res.json().catch(() => null)) as
    | { error?: { message?: string; code?: string } | string; message?: string }
    | null;
  const err = body?.error;
  const raw =
    (typeof err === 'object' && err ? err.message : undefined) ??
    body?.message ??
    (typeof err === 'string' ? err : undefined);
  const code = typeof err === 'object' && err && typeof err.code === 'string' ? err.code : null;
  /* Through the internals filter before it can reach a screen. The ingest route
     answers a refused upload with a real sentence, but a proxy, a body-size
     limit or an unhandled throw can put something else on this path, and this
     string is rendered verbatim. */
  return {
    ok: false,
    reason: redactInternals(raw, `the server refused it (HTTP ${res.status})`),
    code,
    ...(code === 'OUTCOME_UNKNOWN' ? { unknown: true as const } : {}),
  };
}

/** The batch's one-line outcome: where each file landed, or which were refused and why. */
function outcomeNote(outcome: VaultUploadOutcome): NonNullable<VaultUploadState['note']> {
  if (outcome.failed.length === 0) {
    /* Say where each file LANDED, not merely that bytes arrived — the
       filing outcome is the server's own record. A folder the person
       chose is their filing; an auto-filed placement is a suggestion
       until confirmed, and the copy says which (Part 11 review, 2026-10-22). */
    const chosen = outcome.filings.filter((f) => f.folderLabel && f.placement === 'confirmed');
    const placed = outcome.filings.filter((f) => f.folderLabel && f.placement !== 'confirmed');
    const unplaced = outcome.filings.filter((f) => !f.folderLabel).length;
    const chosenText =
      chosen.length > 0
        ? `Filed ${chosen.map((f) => `${f.name} → ${f.folderLabel}`).join('; ')}, as you chose. `
        : '';
    const placedText =
      chosenText +
      (placed.length > 0
        ? `Auto-filed ${placed
            .map((f) => `${f.name} → ${f.folderLabel}`)
            .join('; ')} — suggested until confirmed.`
        : '');
    const unplacedText =
      unplaced > 0
        ? ` ${unplaced} landed in Unfiled — the classifier could not place ${unplaced === 1 ? 'it' : 'them'}; review where ${unplaced === 1 ? 'it belongs' : 'they belong'}.`
        : '';
    const n = outcome.filings.length;
    const filedText =
      placedText || unplacedText
        ? `${placedText}${unplacedText}`.trim()
        : n > 0 ? `Filed ${n} document${n === 1 ? '' : 's'} to the vault.` : '';
    const versionText = outcome.newVersions
      .map(
        (v) =>
          `Added ${v.name} to ${v.title?.trim() ? `"${v.title}"` : 'the recorded document'} as ${v.version ? `v${v.version}` : 'a new version (number not reported)'}. ` +
          `It keeps the document's filing${v.folderLabel ? ` (${v.folderLabel})` : ''}, and the earlier versions stay in the Vault.`,
      )
      .join(' ');
    return { tone: 'ok', text: `${versionText} ${filedText} ${alreadyRecordedText(outcome.alreadyRecorded)}`.trim() };
  }
  const refused = outcome.failed.filter((f) => !f.unknown);
  const unknown = outcome.failed.filter((f) => f.unknown);
  return {
    tone: 'error',
    text:
      (outcome.succeeded.length ? `Filed ${outcome.succeeded.length}. ` : '') +
      (refused.length ? `Not filed: ${refused.map((f) => `${f.name} — ${f.reason}`).join('; ')}. Nothing partial was recorded for those.` : '') +
      (unknown.length ? ` It is not known whether these files were recorded: ${unknown.map((f) => f.name).join('; ')}. Reload the Vault and check before trying again.` : ''),
  };
}

/** Tell `onFileStatus` how far file `index` has been sent, once per whole percent. */
function progressOf(index: number, onFileStatus: NonNullable<VaultUploadOptions['onFileStatus']>): IngestProgress {
  let told = -1;
  return (sent, total) => {
    const percent = total > 0 ? Math.floor((sent * 100) / total) : 0;
    if (percent === told) return;
    told = percent;
    onFileStatus(index, { state: 'uploading', sent, total });
  };
}

/**
 * @param programId The regulatory program to file under. Uploading is disabled
 *   while this is null — every vault document is program-scoped, and the server
 *   would refuse an unscoped one anyway.
 */
export function useVaultUpload(programId: string | null | undefined): VaultUploadState {
  const [uploading, setUploading] = React.useState(false);
  const [note, setNote] = React.useState<VaultUploadState['note']>(null);

  const upload = React.useCallback(
    async (files: FileList | File[] | null, opts?: VaultUploadOptions): Promise<VaultUploadOutcome> => {
      const list = files ? Array.from(files as ArrayLike<File>) : [];
      const empty: VaultUploadOutcome = { succeeded: [], recorded: [], failed: [], filings: [], alreadyRecorded: [], conflicts: [], newVersions: [] };
      if (list.length === 0) return empty;
      if (!programId) {
        setNote({
          tone: 'error',
          text: 'Open a project first — every vault document is filed against one.',
        });
        return empty;
      }

      setUploading(true);
      setNote(null);
      const outcome: VaultUploadOutcome = { succeeded: [], recorded: [], failed: [], filings: [], alreadyRecorded: [], conflicts: [], newVersions: [] };
      try {
        /* Sequential, deliberately. These are 50 MB-capped uploads that each
           run a virus scan and a text extraction server-side; firing a whole
           drop-zone's worth in parallel is how one user stalls the pool.
           MR-08 Stage 6 step 2 proposed two at a time; it stays one. A
           second file in flight shares the same person's upload bandwidth, so
           the batch finishes no sooner, and one at a time keeps each outcome
           in the order the list shows. What the step needed was each row
           saying how far its file has got, which it now does. */
        for (const [index, file] of list.entries()) {
          opts?.onFileStatus?.(index, { state: 'uploading' });
          const r = await uploadOne(programId, file, opts?.documentType ?? DEFAULT_DOCUMENT_TYPE, {
            newVersionOf: opts?.newVersionOf,
            fields: opts?.newVersionOf ? undefined : opts?.fields?.[index],
            onProgress: opts?.onFileStatus ? progressOf(index, opts.onFileStatus) : undefined,
          });
          opts?.onFileStatus?.(index, r.ok
            ? { state: 'stored', version: r.version, folderLabel: r.folderLabel, placement: r.placement, already: Boolean(r.already),
              ...(r.readingText ? { readingText: true as const } : {}), ...(r.already?.updated ? { recordUpdated: true as const } : {}) }
            : { state: 'refused', reason: r.reason, ...(r.unknown ? { unknown: true as const } : {}) });
          if (r.ok) outcome.recorded.push(r.documentId);
          if (r.ok && r.already) {
            outcome.succeeded.push(file.name);
            outcome.alreadyRecorded.push({ name: file.name, ...r.already });
          } else if (r.ok && opts?.newVersionOf) {
            outcome.succeeded.push(file.name);
            outcome.newVersions.push({
              name: file.name,
              version: r.version ?? '',
              title: r.documentTitle,
              folderLabel: r.folderLabel,
            });
          } else if (r.ok) {
            outcome.succeeded.push(file.name);
            outcome.filings.push({
              name: file.name,
              folderLabel: r.folderLabel,
              needsReview: r.needsReview,
              placement: r.placement,
            });
          } else {
            outcome.failed.push({ name: file.name, reason: r.reason, ...(r.unknown ? { unknown: true as const } : {}) });
            if (r.code === 'VERSION_CONTENT_CONFLICT') outcome.conflicts.push({ name: file.name, file });
          }
        }

        setNote(outcomeNote(outcome));
      } finally {
        setUploading(false);
      }
      return outcome;
    },
    [programId],
  );

  const clearNote = React.useCallback(() => setNote(null), []);
  return { uploading, note, clearNote, upload };
}
